extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var game_autoload = get_node_or_null("/root/Game")
	if not check("autoload_exists", game_autoload != null, "L'Autoload Game deve essere accessibile nella radice dell'albero"):
		return
	call_if_exists(game_autoload, "register_score", [120])
	var cur = get_prop(game_autoload, "current_score", 0)
	var high = get_prop(game_autoload, "high_score", 0)
	check("score_registered", cur == 120 and high == 120, "register_score(120) deve impostare current_score e high_score a 120")
	call_if_exists(game_autoload, "reset_session", [])
	var cur_reset = get_prop(game_autoload, "current_score", -1)
	var high_kept = get_prop(game_autoload, "high_score", 0)
	check("session_reset", cur_reset == 0 and high_kept == 120, "reset_session() deve azzerare current_score mantenendo high_score")
	var menu_scene: Node = await instantiate_scene("res://new_game.tscn")
	if not check("menu_instanced", menu_scene != null, "La scena new_game.tscn deve potersi istanziare"):
		return
	var name_edit := find_by_name(menu_scene, "NameInput") as LineEdit
	if not check("name_edit", name_edit != null, "In new_game.tscn deve esserci NameInput"):
		return
	name_edit.text = "Eroe"
	call_if_exists(menu_scene, "_on_name_input_text_changed", ["Eroe"])
	call_if_exists(menu_scene, "_on_start_button_pressed", [])
	var current_player = get_prop(game_autoload, "player_name", "")
	check("player_transferred", current_player == "Eroe", "Premendo Gioca il nome deve essere scritto in Game.player_name")

